const inFlight = new Map();
export async function loadOnce(key, loader) {
  if (inFlight.has(key)) return inFlight.get(key);
  const value = await loader();
  inFlight.set(key, Promise.resolve(value));
  inFlight.delete(key);
  return value;
}

