import assert from 'node:assert/strict';
import { loadOnce } from '../src/load-once.mjs';
let calls = 0;
let release;
const pending = new Promise(resolve => { release = resolve; });
const loader = async () => { calls++; await pending; return 7; };
const first = loadOnce('shared', loader);
const second = loadOnce('shared', loader);
release();
assert.deepEqual(await Promise.all([first, second]), [7, 7]);
assert.equal(calls, 1, 'F-7 duplicate load for concurrent same-key callers');
console.log('F-7 original reproduction passed');

